const handleArrowUp = (e: KeyboardEvent) => {
  e.preventDefault();
  const currentItem = document.activeElement;
  const prevItem = currentItem?.previousElementSibling?.querySelector('[tabindex="0"]');
  if (prevItem) {
    (prevItem as HTMLElement).focus();
  }
};

const handleArrowDown = (e: KeyboardEvent) => {
  e.preventDefault();
  const currentItem = document.activeElement;
  const nextItem = currentItem?.nextElementSibling?.querySelector('[tabindex="0"]');
  if (nextItem) {
    (nextItem as HTMLElement).focus();
  }
};
