import { defineStore } from 'pinia';
import type { UserProfile, ProfileUpdateRequest, PasswordChangeRequest } from '~/types/profile';

export const useUserStore = defineStore('user', {
  state: () => ({
    userProfile: null as UserProfile | null,
    loading: false,
    error: null as string | null,
  }),

  getters: {
    fullName: (state) => state.userProfile?.userName || '',
    hasAvatar: (state) => !!state.userProfile?.avatarUrl,
    profileCompleteness: (state) => {
      if (!state.userProfile) return 0;
      const fields = ['userName', 'bio', 'phone', 'avatarUrl'];
      const filled = fields.filter(f => state.userProfile?.[f]);
      return Math.round((filled.length / fields.length) * 100);
    },
  },

  actions: {
    async fetchProfile(userId: string) {
      this.loading = true;
      this.error = null;
      try {
        const response = await $fetch<{ success: boolean; data: UserProfile }>(
          `/api/users/${userId}/profile`
        );
        if (response.success) {
          this.userProfile = response.data;
        }
        return response.data;
      } catch (error: any) {
        this.error = error.message;
        throw error;
      } finally {
        this.loading = false;
      }
    },

    async updateProfile(userId: string, data: ProfileUpdateRequest) {
      this.loading = true;
      try {
        const response = await $fetch(`/api/users/${userId}/profile`, {
          method: 'PUT',
          body: data,
        });
        if (response.success) {
          this.userProfile = { ...this.userProfile, ...response.data };
        }
        return response;
      } finally {
        this.loading = false;
      }
    },

    async changePassword(userId: string, data: PasswordChangeRequest) {
      this.loading = true;
      try {
        return await $fetch(`/api/users/${userId}/password`, {
          method: 'PUT',
          body: data,
        });
      } finally {
        this.loading = false;
      }
    },

    async uploadAvatar(userId: string, file: File) {
      const formData = new FormData();
      formData.append('avatar', file);
      const response = await $fetch(`/api/users/${userId}/avatar`, {
        method: 'POST',
        body: formData,
      });
      if (response.success) {
        this.userProfile = { ...this.userProfile, avatarUrl: response.avatarUrl };
      }
      return response;
    },

    async deleteAccount(userId: string, password: string) {
      return await $fetch(`/api/users/${userId}`, {
        method: 'DELETE',
        body: { password },
      });
    },
  },
});
